globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2015,"grade":"8-9","contest":"КИТ","letters":"АБВГ","count":26,"language":"ru","points":3,"tasksFile":"8-9.pdf","answersFile":"reviewed-8-9.pdf","sections":[{"start":1,"title":"Задания на 3 балла"},{"start":11,"title":"Задания на 4 балла"},{"start":21,"title":"Задания на 5 баллов"},{"start":24,"title":"Числовой ответ"}],"reviewedKey":true}, [{"number":1,"title":"Свет для театра теней","question":"Что из перечисленного наиболее подходит в качестве источника яркого света в театре теней, где зрители видят лишь тени актёров на полотне?","choices":["Принтер","Граммофон","Мобильный телефон","Проектор"],"points":3,"steps":["Чтобы получить тени на полотне, нужен достаточно яркий свет, направленный на полотно. Актёры перекрывают этот свет и образуют силуэты.","Принтер печатает на бумаге, граммофон воспроизводит звук. Экран телефона светится, но широкого светового пучка не создаёт. Объектив проектора направляет на полотно яркий свет."],"answer":3,"optionFigures":[{"src":"assets/kit/2015/8-9-01-a.webp","alt":"Принтер.","width":126,"height":89},{"src":"assets/kit/2015/8-9-01-b.webp","alt":"Граммофон.","width":85,"height":103},{"src":"assets/kit/2015/8-9-01-c.webp","alt":"Мобильный телефон.","width":125,"height":98},{"src":"assets/kit/2015/8-9-01-d.webp","alt":"Проектор.","width":127,"height":79}]},{"number":2,"title":"Косточки на счётах","question":"Какое число отложено на счётах?","choices":["215","2015","8","2,51"],"points":3,"steps":["Считаем косточки, сдвинутые влево. Ряд непосредственно над коротким четырёхкосточковым рядом показывает единицы: их пять.","Выше отложены один десяток, ноль сотен и две тысячи. Получается 2000 + 10 + 5 = 2015."],"answer":1,"figure":{"src":"assets/kit/2015/10-11-02.svg","alt":"Русские счёты. Считывай косточки, отделённые влево. Короткий ряд состоит из четырёх косточек.","width":286,"height":322}},{"number":3,"title":"Интернет-сервисы","question":"Установите соответствие между сервисами и их названиями.\na. Twitter\nb. Instagram\nc. ВКонтакте\nd. Foursquare\n\n1. Отзывы о посещаемых местах.\n2. Публикация фотографий.\n3. Крупнейшая в России социальная сеть.\n4. Ведение микроблогов.","choices":["1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-c, 2-a, 3-d, 4-b"],"points":3,"steps":["В 2015 году Foursquare был известен отзывами о местах, а Instagram — публикацией фотографий. Получаем 1-d и 2-b.","ВКонтакте — российская социальная сеть, Twitter — сервис коротких записей для микроблогов. Получаем 3-c и 4-a."],"answer":1,"adaptation":"Сервисы описаны по их назначению на момент конкурса в 2015 году."},{"number":4,"title":"Операционные системы","question":"Что из перечисленного не относится к операционным системам?","choices":["DOS","Linux","LPT","iOS"],"points":3,"steps":["DOS, Linux и iOS управляют работой устройства и позволяют запускать программы.","LPT — это обозначение параллельного порта. Через него, например, подключали принтер."],"answer":2},{"number":5,"title":"Устройство Энгельбарта","question":"В 1970 году Д. Энгельбарт запатентовал устройство X-Y position indicator for a display system. Сегодня это устройство называется…","choices":["клавиатурой","мышью","процессором","маршрутизатором"],"points":3,"steps":["Название можно перевести как «указатель положения X–Y для системы отображения». X и Y — две координаты на экране.","Движение компьютерной мыши по столу меняет положение указателя на экране по горизонтали и вертикали."],"answer":1},{"number":6,"title":"Виды шрифтов","question":"Установите соответствие между образцами шрифтов и их видами.\na. Декоративный.\nb. Рукописный.\nc. С засечками.\nd. Рубленый.","choices":["1-d, 2-c, 3-a, 4-b","1-b, 2-c, 3-d, 4-a","1-a, 2-b, 3-c, 4-d","1-c, 2-d, 3-b, 4-a"],"points":3,"steps":["У «Гротеска» (1) концы штрихов ровные, без засечек. Это рубленый шрифт. В слове Roman (2) у концов штрихов видны засечки.","Образец 3 узнаётся по украшенным ломаным буквам, а в образце 4 плавно соединённые наклонные буквы напоминают письмо от руки. Значит, 3-a и 4-b."],"answer":0,"figures":[{"src":"assets/kit/2015/8-9-06-1.svg","alt":"Слово «Гротеск», концы штрихов ровные.","caption":"1","width":81,"height":17},{"src":"assets/kit/2015/8-9-06-2.svg","alt":"Слово Roman, на концах штрихов короткие выступы.","caption":"2","width":45,"height":18},{"src":"assets/kit/2015/8-9-06-3.webp","alt":"Три орнаментальные латинские буквы с ломаными контурами.","caption":"3","width":90,"height":38},{"src":"assets/kit/2015/8-9-06-4.svg","alt":"Слово «Шрифты» с наклонными соединёнными буквами.","caption":"4","width":57,"height":15}]},{"number":7,"title":"Значки подключения","question":"Установите соответствие между значками и их обозначениями.\na. Беспроводная локальная сеть.\nb. USB.\nc. Bluetooth.","choices":["1-a, 2-b, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b"],"points":3,"steps":["У Bluetooth угловатый белый знак на синем фоне. У USB значок похож на ветку с кругом, квадратом и стрелкой на концах.","Дуги над точкой — знак беспроводной локальной сети Wi-Fi. Получаем 1-c, 2-b, 3-a."],"answer":2,"figures":[{"src":"assets/kit/2015/8-9-07-1.webp","alt":"Белый угловатый знак на синем овале.","caption":"1","width":60,"height":87},{"src":"assets/kit/2015/8-9-07-2.webp","alt":"Три ответвления заканчиваются кругом, квадратом и стрелкой.","caption":"2","width":114,"height":61},{"src":"assets/kit/2015/8-9-07-3.webp","alt":"Три дуги над точкой.","caption":"3","width":78,"height":73}]},{"number":8,"title":"Перестановка скобок","question":"Дана последовательность скобок ({){]}[}. За какое наименьшее количество перестановок соседних элементов её можно привести к виду {(){[]}}?","choices":["5","2","3","4"],"points":3,"steps":["Скобка «(» должна встать после первой «{», а «[» — перед «]» и первой «}». Это три изменения порядка, каждое требует отдельного обмена соседей.","Сначала меняем местами первые два символа. Затем дважды переносим «[» влево: ({){]}[} → {(){]}[} → {(){][}} → {(){[]}}."],"answer":2},{"number":9,"title":"Форматы файлов","question":"Какой из перечисленных форматов не является форматом графического файла?","choices":["bmp","html","jpg","gif"],"points":3,"steps":["BMP, JPG и GIF хранят изображения. GIF также может содержать последовательность кадров.","HTML хранит разметку веб-страницы. В неё можно вставить изображение, но сам HTML-файл остаётся документом с разметкой."],"answer":1},{"number":10,"title":"Удаление символов","question":"Какие клавиши можно использовать для удаления символов?","choices":["Delete и Backspace","Backspace и Caps Lock","Break и Delete","Page Down и Caps Lock"],"points":3,"steps":["Поставь курсор между двумя буквами. Backspace удалит букву слева, Delete — справа.","Caps Lock переключает регистр, Page Down перемещает страницу вниз, Break служит для прерывания. Обе клавиши удаления есть только в первой паре."],"answer":0},{"number":11,"title":"Масштаб рисунка","question":"Лэйла создала рисунок размером 800 × 600 пикселей. Затем она уменьшила его, сохраняя пропорции так, чтобы размер меньшей стороны стал равен 480 пикселей. Чему равен новый размер большей стороны?","choices":["680","640","600","800"],"points":4,"steps":["Меньшая сторона была 600 пикселей и стала 480. Масштаб уменьшения равен 480 ÷ 600 = 4/5.","При сохранении пропорций у обеих сторон один масштаб. Большая сторона станет 800 × 4/5 = 640 пикселей."],"answer":1},{"number":12,"title":"Счастливое время","question":"Назовём время счастливым, если цифры на электронных часах читаются одинаково слева направо и справа налево. Часы показывают 20:02. Сколько часов и минут прошло с момента предыдущего счастливого времени?","choices":["4 ч 51 мин","4 ч 11 мин","17 ч 42 мин","51 мин"],"points":4,"steps":["У счастливого времени минуты записываются цифрами часа в обратном порядке. Перед 20:02 проверяем часы 19, 18, 17 и 16. Получились бы 91, 81, 71 и 61 минута, а в часе только 60 минут.","Для 15 получаем настоящее время 15:51. От 15:51 до 20:00 проходит 4 ч 9 мин, до 20:02 — ещё 2 мин."],"answer":1},{"number":13,"title":"Расходы в путешествии","question":"Четверо друзей во время путешествия платили за разные мероприятия по очереди. После возвращения они пересчитали траты. Стоимость каждого мероприятия делится поровну между всеми его участниками. Кто после взаимного расчёта получит наибольшую сумму?\n\nЗавтрак: Маша заплатила 24. Участвовали Маша, Коля, Даша.\nЭкскурсия: Коля заплатил 36. Участвовали Коля, Даша, Паша.\nОбед: Даша заплатила 60. Участвовали все четверо.\nУжин: Паша заплатил 48. Участвовали Маша, Коля, Паша.","choices":["Маше","Коле","Даше","Паше"],"points":4,"steps":["Поделим каждую сумму на число участников. Доля за завтрак — 8, за экскурсию — 12, за обед — 15, за ужин — 16.","Даша участвовала в первых трёх мероприятиях. Её доля равна 8 + 12 + 15 = 35, а она заплатила 60, поэтому ей вернут 25.","Паша заплатил на 5 больше своей доли (48 − 43), а Маша и Коля заплатили на 15 меньше своей доли каждый. Самую большую сумму получит Даша."],"answer":2},{"number":14,"title":"Шифр для переписки","question":"Алина и Юля шифруют слова. Для каждого слова у них есть ключ — натуральное число. Слово «падеж» с ключом 4 превращается в «паедеже», «синтезатор» с ключом 2 — в «синитеизаитори», «зависать» с ключом 7 — в «затвитсатьт». Как они запишут слово «компилятор» с ключом 2?","choices":["комопиоляоторо","кимполотяро","комоляторо","компиоляторо"],"points":4,"steps":["Разбей примеры на слоги: «па-деж», «син-те-за-тор», «за-ви-сать». После каждого слога добавлена одна и та же буква.","Ключ показывает номер добавляемой буквы в исходном слове. В «падеж» это четвёртая буква «е», в «синтезатор» — вторая «и», в «зависать» — седьмая «т».","В «компилятор» вторая буква — «о». После добавления «о» к слогам «ком-пи-ля-тор» получается «комо-пио-ляо-торо»."],"answer":0},{"number":15,"title":"Создатели языков","question":"Кто из перечисленных людей не является разработчиком какого-либо языка программирования?","choices":["Б. Паскаль","Б. Страуструп","Дж. Бэкус","Н. Вирт"],"points":4,"steps":["Бьёрн Страуструп создал C++, Джон Бэкус руководил созданием Fortran, Никлаус Вирт разработал Pascal.","Язык Pascal назвали в честь Блеза Паскаля, математика XVII века. Его создал Никлаус Вирт."],"answer":0},{"number":16,"title":"Имя в телефоне","question":"При поиске контакта с помощью Т9 Маша ввела 2454539. Одну лишнюю клавишу она нажала по ошибке. Какое имя она искала? Группы букв показаны на клавиатуре.","choices":["Володя","Алексей","Марина","Виктор"],"points":4,"steps":["Одна клавиша кодирует любую букву из подписанной на ней группы. «Володя» даёт В→2, О→5, Л→4, О→5, Д→3, Я→9: это 254539.","Из набора 2454539 достаточно удалить вторую цифру 4, чтобы осталось 254539. Остальные имена так не кодируются."],"answer":0,"adaptation":"Уточнено, что ошибочное нажатие было лишним.","figure":{"src":"assets/kit/2015/10-11-18.svg","alt":"Телефонная клавиатура Т9 с русскими буквами. 2 — АБВГ, 3 — ДЕЖЗ, 4 — ИЙКЛ, 5 — МНОП, 6 — РСТУ, 7 — ФХЦЧ, 8 — ШЩЪЫ, 9 — ЬЭЮЯ.","width":316,"height":183}},{"number":17,"title":"Цифры по алфавиту","question":"Расположим по алфавиту десять слов, обозначающих цифры в десятичной системе счисления. Возьмём первые три из них и из соответствующих цифр составим наименьшее возможное трёхзначное число без повторений. Какое это число?","choices":["102","289","123","208"],"points":4,"steps":["По алфавиту раньше всех названий идут «восемь», затем «два» и «девять». Берём цифры 8, 2 и 9.","Чтобы число было наименьшим, ставим самую маленькую цифру в сотни, следующую по величине — в десятки. Получаем 289."],"answer":1},{"number":18,"title":"Звук и видео","question":"Какой интерфейс передачи данных позволяет одновременно передавать видео и звуковой сигнал?","choices":["VGA","LPT","HDMI","COM"],"points":4,"steps":["VGA передаёт изображение. Для звука при таком подключении обычно нужен отдельный кабель.","LPT и COM служат для подключения периферии. HDMI передаёт цифровое изображение и звук по одному кабелю."],"answer":2},{"number":19,"title":"Значки планшета","question":"На экране планшета помещаются четыре значка приложений вдоль короткой стороны и пять вдоль длинной. Значки нумеруются слева направо и от верхней строки к нижней. В вертикальной ориентации значок находится в строке 4, столбце 1. Где он окажется при горизонтальной ориентации, если порядок значков сохраняется?","choices":["1–4","3–3","4–1","2–5"],"points":4,"steps":["В вертикальной ориентации в строке четыре значка. До четвёртой строки идут 3 × 4 = 12 значков. Первый в этой строке имеет номер 13.","В горизонтальной ориентации в строке пять значков. Первые два ряда занимают десять значков. Тринадцатый стоит в третьем столбце третьей строки."],"answer":1,"figure":{"src":"assets/kit/2015/10-11-19.svg","alt":"Планшет в вертикальной ориентации: пять рядов по четыре значка в каждом.","width":186,"height":211}},{"number":20,"title":"Стеклянные стены","question":"Архитектор Стройкин проектирует дом, в котором две стены из стекла, а две из бетона. На схеме показаны этаж и формы комнат. Комнаты можно поворачивать и повторять. Каждая комната должна стороной клетки примыкать к стеклянной стене. Не занятое комнатами пространство отводится под техническое помещение. Сколько комнат можно разместить самое большее?","choices":["8","9","10","11"],"points":4,"steps":["На этаже 8 × 5 = 40 клеток. Каждая из пяти разрешённых фигур занимает четыре клетки. Больше 40 ÷ 4 = 10 комнат не поместится.","В следующей раскладке каждая буква обозначает одну комнату. Прочитай пять строк сверху вниз: AABBCCDD / AABBCCDD / EEFFGGHH / EIIFGJJH / EIIFGJJH.","В первых двух рядах четыре квадрата примыкают к верхней стене. В трёх нижних рядах четыре угловые комнаты E, F, G, H и два квадрата I, J примыкают к нижней."],"answer":2,"adaptation":"Уточнено, что формы комнат можно поворачивать и повторять.","figure":{"src":"assets/kit/2015/8-9-20.webp","alt":"Этаж из восьми столбцов и пяти строк. Верхняя и нижняя стены стеклянные. Рядом показаны пять форм комнат по четыре клетки.","width":379,"height":144}},{"number":21,"title":"Часы заполняют экран","question":"Четыре цифры высотой шесть клеток строятся построчно, сдвигаясь справа налево. Внутри каждой строки расстояния между закрашенными клетками сохраняются. Первая строка уже остановилась. Какое время покажут часы на рисунке?","choices":["01:45","04:46","21:34","22:53"],"points":5,"steps":["Строки можно сдвигать только целиком. В первой строке первые две соседние закрашенные клетки похожи на верх нуля. Попробуй поставить две средние стороны нуля под ними, сохраняя промежуток между клетками.","Оставь первую строку на месте и сдвинь строки со второй по шестую соответственно на 3, 4, 4, 6 и 8 клеток влево. Теперь видно все четыре цифры: 0, 1, 4, 5."],"answer":0,"figure":{"src":"assets/kit/2015/10-11-21.svg","alt":"Экран формирующихся часов в клетках. Верхняя из шести строк уже остановилась, остальные сдвигаются.","width":348,"height":109}},{"number":22,"title":"Редактирование котом","question":"Кот набрал строку. Знайка поставил курсор в её конец и выполнил команды: влево, влево, Backspace, влево, пробел, влево, влево, пробел, влево, влево, Delete. Получилось «кит и кот». Какая строка могла быть вначале? Backspace удаляет символ слева от курсора, Delete — справа.","choices":["ктитикрот","кит и крот","кити крот","киттикрот"],"points":5,"steps":["Возьмём строку «киттикрот». Два движения влево дают «киттикр|от». Backspace стирает «р», а ещё одно движение влево ставит курсор перед «кот»: «китти|кот».","Вставляем пробел: «китти |кот». Два движения влево и второй пробел дают «китт |и кот».","Ещё два движения влево дают «кит|т и кот». Delete удаляет вторую «т», остаётся «кит и кот». Из варианта В та же последовательность удаляет «и» и оставляет «кит» и «кот» с тремя пробелами."],"answer":3},{"number":23,"title":"Способы ввода пароля","question":"Аскар придумал текстовый пароль из пяти символов. Для каждой позиции разрешено выбрать любой из пяти символов алфавита. Графический ключ Артёма обходит все вершины рисунка по одному разу, в любом порядке. В каком рисунке число графических ключей наиболее близко к числу текстовых паролей Аскара?","choices":["Четыре вершины","Пять вершин","Шесть вершин","Семь вершин"],"points":5,"steps":["В каждой из пяти позиций есть пять вариантов. Число текстовых паролей равно 5 × 5 × 5 × 5 × 5 = 3125.","Для n вершин на первом шаге доступно n вершин, на втором n − 1, потом n − 2, и так далее. Получаем 24, 120, 720 и 5040 способов.","До 720 не хватает 2405, до 5040 — 1915. Числа 24 и 120 ещё дальше от 3125, чем 720. Значит, подходит схема с семью вершинами."],"answer":3,"adaptation":"Уточнено, что символы текстового пароля могут повторяться и вершины можно обходить в любом порядке.","optionFigures":[{"src":"assets/kit/2015/10-11-22-a.svg","alt":"Схема из 4 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-b.svg","alt":"Схема из 5 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-c.svg","alt":"Схема из 6 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-d.svg","alt":"Схема из 7 вершин.","width":128,"height":128}]},{"number":24,"title":"Цифры лепрекона","question":"Лепрекон Вася снимал коины в банкомате. Сначала он набрал цифры #, æ, Ω, затем æ, #, Ω. В третий раз он попытался снять 117 коинов, но средств уже не хватило. Три разных знака обозначают три разные десятичные цифры. Чему равна цифра Ω, если сначала на карте было 2000 коинов?","choices":[],"points":5,"steps":["Пусть # — цифра x, æ — цифра y, Ω — цифра z. Вместе Вася снял (100x + 10y + z) + (100y + 10x + z) = 110(x + y) + 2z коинов.","Осталось меньше 117 коинов, поэтому Вася снял как минимум 1884. Максимальная сумма двух разных цифр x и y равна 8 + 9 = 17. При x + y ≤ 16 даже с z = 9 получилось бы лишь 1778.","Значит, x и y — 8 и 9. Тогда снято 1870 + 2z, откуда z ≥ 7. Цифры 8 и 9 уже заняты, поэтому z = 7. На карте остаётся 116 коинов."],"numericAnswer":7,"adaptation":"Уточнено, что разные лепреконские значки обозначают разные десятичные цифры."},{"number":25,"title":"Квадрат из ромашек","question":"Эля заполнила текстовый документ смайликами, ромашками, сердечками и звёздочками. Сначала в строке помещалось ровно 17 картинок. При увеличении полей картинки, которые не помещаются в строку, перемещаются в следующую. Квадрат какой наибольшей площади сможет получить Эля из ромашек, меняя размеры полей? Площадь каждого символа равна 1. Разрешено использовать часть ромашек.","choices":[],"points":5,"steps":["На рисунке в конце второй строки 4 ромашки, в третьей 17, в начале четвёртой 7. Всего 28 ромашек. Для квадрата 6 × 6 потребовалось бы 36.","Перед ромашками идут 17 + 13 = 30 смайликов. Если оставить в строке по 5 картинок, смайлики заполнят ровно шесть строк. Тогда следующие 25 картинок — ромашки — займут пять полных строк по пять.","Из этих пяти строк получается квадрат площадью 25."],"numericAnswer":25,"figure":{"src":"assets/kit/2015/8-9-25.webp","alt":"На листе 17 картинок в полной строке. Смайлики, ромашки, сердечки и звёздочки идут группами без промежутков.","width":393,"height":175}},{"number":26,"title":"Время скачивания","question":"Кирилл скачивает файл. Программа рассчитывает оставшееся время по размеру ещё не скачанной части и скорости в текущий момент. Через 28 минут было скачано 80% файла. Сколько минут до окончания покажет программа через 34 минуты после начала? График показывает скорость в процентах от максимально возможной.","choices":[],"points":5,"steps":["Измерим объём в максимальных минутных порциях. До 24-й минуты скорость равна 60%, потом до 28-й — 40%. За это время скачано 24 × 0,6 + 4 × 0,4 = 16 порций. Это 80% файла, всего нужно 20 порций.","С 28-й по 32-ю минуту скачано ещё 4 × 0,2 = 0,8 порции, а с 32-й по 34-ю — 2 × 0,8 = 1,6. Остаток равен 20 − 16 − 0,8 − 1,6 = 1,6.","В момент 34 минуты скорость 0,8 порции в минуту. Программа прогнозирует ещё 1,6 ÷ 0,8 = 2 минуты."],"numericAnswer":2,"figure":{"src":"assets/kit/2015/8-9-26.webp","alt":"Ступенчатый график скорости: 60% до 24 мин, 40% до 28, 20% до 32, 80% до 36, 40% до 44, затем снова 60%.","width":264,"height":187}}]);
edition.sources.readers = {"tasksUrl":"assets/kit/2015/8-9-reading.pdf"};
